use serde_json::{Value, json};
use t3_client::thread_views::{
    composer::editor::{BuildOptions, build_document, surround_selection},
    rich_text::Mark,
};
fn canonical(value: &mut Value) {
    match value {
        Value::Array(values) => {
            for value in values.iter_mut() {
                canonical(value);
            }
            let mut result: Vec<Value> = Vec::new();
            for node in std::mem::take(values) {
                if node["type"] == "text"
                    && result.last().is_some_and(|last| {
                        last["type"] == "text" && last["marks"] == node["marks"]
                    })
                {
                    let last = result.last_mut().expect("valid fixture");
                    last["text"] = json!(format!(
                        "{}{}",
                        last["text"].as_str().expect("valid fixture"),
                        node["text"].as_str().expect("valid fixture")
                    ));
                } else {
                    result.push(node);
                }
            }
            *values = result;
        }
        Value::Object(values) => {
            values.retain(|key, value| {
                key != "citeKey"
                    && !(matches!(key.as_str(), "marks" | "content")
                        && value.as_array().is_some_and(Vec::is_empty))
                    && !(key == "attrs" && value.as_object().is_some_and(serde_json::Map::is_empty))
            });
            if let Some(marks) = values.get_mut("marks").and_then(Value::as_array_mut) {
                marks.sort_by_key(|mark| mark["type"].as_str().expect("valid fixture").to_owned());
            }
            for value in values.values_mut() {
                canonical(value);
            }
        }
        _ => {}
    }
}
#[test]
fn surround_preserves_exact_restorable_marks_and_atom_payloads() {
    let cases: Value = serde_json::from_str(GOLDENS).expect("valid fixture");
    let mut failures = Vec::new();
    for case in cases.as_array().expect("valid fixture") {
        let source = case["text"].as_str().expect("valid fixture");
        let document = build_document(
            source,
            BuildOptions::default(),
            |id| Some((id.into(), None)),
            |_, _| false,
        );
        for range in case["ranges"].as_array().expect("valid fixture") {
            let from = range[0].as_u64().expect("valid fixture") as usize;
            let to = range[1].as_u64().expect("valid fixture") as usize;
            let mark = if range[2] == "*" {
                Mark::Italic
            } else {
                Mark::Code
            };
            let mut actual = surround_selection(&document, from, to, mark).unwrap_or(Value::Null);
            canonical(&mut actual);
            let mut expected = range[3].clone();
            canonical(&mut expected);
            if actual != expected {
                failures.push(format!(
                    "{source:?} {from}..{to} {:?}: {actual} != {expected}",
                    range[2]
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 15:\n{}",
        failures.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
